    private void migrateCredits(){
        if(!prefs.getBoolean("v12_credit_migration",false)){
            int credits=prefs.getInt("reward_credits",0);
            prefs.edit().putInt("reward_credits",credits).putBoolean("v12_credit_migration",true).apply();
        }
    }

