    private List<Task> tasksToday(){return tasksFor(Calendar.getInstance());}
    private List<Task> tasksFor(Calendar d){List<Task>a=new ArrayList<>();int day=d.get(Calendar.DAY_OF_WEEK);a.add(t("fajr",240,390,"الفجر والحلقة والدرس","الدين والمسجد",5,true,"mosque"));if(day==Calendar.SATURDAY)a.add(t("workoutA",390,420,"تمرين A — كتف وذراعان + جسم كامل","الصحة",20,true,"health"));if(day==Calendar.TUESDAY)a.add(t("workoutB",390,420,"تمرين B — أوتار وقبضة وسرعة","الصحة",20,true,"health"));a.add(t("english",420,480,englishTitle(day),"الإنجليزية والقبول",day==Calendar.FRIDAY?10:25,day!=Calendar.FRIDAY,"headphones"));a.add(t("sleep2",480,570,"النوم التكميلي","الصحة",5,true,"moon"));a.add(t("leap1",570,600,"LeapAhead — الكتاب ١","المعرفة والقراءة",7,true,"book"));a.add(t("work",600,690,workTitle(day),"العمل والدخل",day==Calendar.FRIDAY?10:25,day!=Calendar.FRIDAY,"briefcase"));a.add(t("quran1",705,780,"القرآن — مراجعة جديدة: صفحتان","القرآن",14,true,"quran"));a.add(t("lunch",780,810,"الغداء","الانضباط",3,true,"meal"));a.add(t("leap2",810,855,"LeapAhead — الكتاب ٢","المعرفة والقراءة",8,true,"book"));a.add(t("quran2",885,970,"القرآن — صفحتان + مراجعة قديمة","القرآن",18,true,"quran"));a.add(afternoon(day));a.add(t("maghrib",1080,1200,"المغرب والتحفيظ والعشاء","الدين والمسجد",5,true,"mosque"));a.add(t("dinner",1200,1230,"العشاء مع الأسرة","الأسرة",3,true,"home"));a.add(t("leap3",1230,1275,"LeapAhead — الكتاب ٣","المعرفة والقراءة",7,false,"book"));a.add(t("close",1320,1340,"إغلاق اليوم وتجهيز الغد","الانضباط",5,true,"check"));a.add(t("sleep",1340,1350,"الاستعداد للنوم","الصحة",5,true,"moon"));addCustom(a,d);return a;}
    private Task afternoon(int day){switch(day){case Calendar.SATURDAY:return t("family_talk",990,1020,"الأسرة + تدريب كلام قصير","الأسرة",8,true,"home");case Calendar.SUNDAY:return t("talk1",990,1020,"تدريب التواصل","التواصل",10,true,"talk");case Calendar.MONDAY:return t("family_friend",990,1020,"خدمة الأسرة + تفقد صديق","الأسرة",8,true,"home");case Calendar.TUESDAY:return t("talk2",990,1020,"تدريب الكلام والحزم","التواصل",10,true,"talk");case Calendar.WEDNESDAY:return t("medicine",990,1050,"مراجعة طب قديم","المعرفة والقراءة",12,true,"book");case Calendar.THURSDAY:return t("khatera",990,1030,"خاطرة دينية + تدريب إلقاء","التواصل",12,true,"talk");default:return t("explore",990,1050,"استكشاف علمي أو مهارة حياة","المعرفة والقراءة",10,false,"discover");}}
    private void addCustom(List<Task>a,Calendar d){try{JSONArray arr=new JSONArray(prefs.getString("custom_tasks","[]"));for(int i=0;i<arr.length();i++){JSONObject o=arr.optJSONObject(i);if(o==null||!o.optBoolean("active",true))continue;int dy=o.optInt("day",0);if(dy!=0&&dy!=d.get(Calendar.DAY_OF_WEEK))continue;a.add(t(o.optString("id","custom_"+i),o.optInt("start",960),o.optInt("end",990),o.optString("title","مهمة مخصصة"),o.optString("domain","الانضباط"),o.optInt("points",10),o.optBoolean("required",false),"check"));}}catch(Exception ignored){}}
    private Task t(String id,int s,int e,String title,String domain,int pts,boolean req,String glyph){return new Task(id,s,e,title,domain,pts,req,glyph);}
    private String englishTitle(int d){switch(d){case Calendar.SATURDAY:return"الإنجليزية: Vocabulary + Reading Explorer";case Calendar.SUNDAY:return"الإنجليزية: Vocabulary + Tactics";case Calendar.MONDAY:return"الإنجليزية: Vocabulary + Reading Explorer";case Calendar.TUESDAY:return"الإنجليزية: Vocabulary + Tactics";case Calendar.WEDNESDAY:return"الإنجليزية: Vocabulary + Oxford Bookworms";case Calendar.THURSDAY:return"اختبار الإنجليزية الأسبوعي";default:return"استماع إنجليزي ممتع — يوم خفيف";}}
    private String workTitle(int d){switch(d){case Calendar.SATURDAY:case Calendar.SUNDAY:return"العمل: تطوير الأكاديمية";case Calendar.MONDAY:case Calendar.TUESDAY:return"العمل: الوصول للسوق";case Calendar.WEDNESDAY:return"العمل: دخل مباشر";case Calendar.THURSDAY:return"العمل: مراجعة الأرقام";default:return"مراجعة مالية خفيفة";}}

    private List<Task> homeTasks(){List<Task> all=tasksToday(),out=new ArrayList<>();int now=Calendar.getInstance().get(Calendar.HOUR_OF_DAY)*60+Calendar.getInstance().get(Calendar.MINUTE);for(Task t:all){if(t.id.equals("sleep2")||t.id.equals("lunch")||t.id.equals("dinner"))continue;if(!done(t)&&t.end>=now-30)out.add(t);if(out.size()>=5)break;}if(out.size()<4)for(Task t:all){if(out.contains(t)||t.id.equals("sleep2")||t.id.equals("lunch")||t.id.equals("dinner"))continue;out.add(t);if(out.size()>=5)break;}return out;}
    private boolean done(Task t){return prefs.getBoolean("reward_done_"+todayKey+"_"+t.id,false);}
    private boolean doneOn(Task t,Calendar d){return prefs.getBoolean("reward_done_"+dateKey(d)+"_"+t.id,false);}
    private void setDone(Task t,boolean val){boolean old=done(t);if(old==val)return;int delta=val?t.points:-t.points;String dk="reward_day_points_"+todayKey,dom="reward_domain_"+t.domain;prefs.edit().putBoolean("reward_done_"+todayKey+"_"+t.id,val).putInt(dk,Math.max(0,prefs.getInt(dk,0)+delta)).putInt(dom,Math.max(0,prefs.getInt(dom,0)+delta)).apply();syncCredits();Toast.makeText(this,val?"+"+t.points+" نقطة":"تم التراجع",Toast.LENGTH_SHORT).show();}
    private int countDoneToday(){int n=0;for(Task t:tasksToday())if(done(t))n++;return n;}private int requiredCountToday(){int n=0;for(Task t:tasksToday())if(t.required)n++;return n;}private int requiredDoneToday(){int n=0;for(Task t:tasksToday())if(t.required&&done(t))n++;return n;}
    private int dayPoints(Calendar c){return prefs.getInt("reward_day_points_"+dateKey(c),0);}private int dayTarget(Calendar c){int n=0;for(Task t:tasksFor(c))if(t.required)n+=t.points;return Math.max(1,n);}private int dayRate(Calendar c){return pct(dayPoints(c),dayTarget(c));}
    private int weekRate(){Calendar start=saturdayStart(Calendar.getInstance()),now=Calendar.getInstance();int p=0,t=0;while(!start.after(now)){p+=dayPoints(start);t+=dayTarget(start);start.add(Calendar.DAY_OF_MONTH,1);}return pct(p,t);}private int monthRate(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int p=0,t=0;while(!c.after(now)){p+=dayPoints(c);t+=dayTarget(c);c.add(Calendar.DAY_OF_MONTH,1);}return pct(p,t);}private int yearRate(){Calendar start=Calendar.getInstance();start.set(2026,Calendar.SEPTEMBER,1,0,0,0);Calendar now=Calendar.getInstance();if(now.before(start))return 0;int p=0,t=0;while(!start.after(now)){p+=dayPoints(start);t+=dayTarget(start);start.add(Calendar.DAY_OF_MONTH,1);}return pct(p,t);}
    private int monthCompleted(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){String k=dateKey(c);for(Task t:tasksFor(c))if(prefs.getBoolean("reward_done_"+k+"_"+t.id,false))n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}private int monthStrongDays(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){if(dayRate(c)>=80)n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}private int monthDonePrefix(String prefix){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){for(Task t:tasksFor(c))if(t.id.startsWith(prefix)&&doneOn(t,c))n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int focusMinutes(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int sum=0;while(!c.after(now)){String k=dateKey(c);for(Task t:tasksFor(c))if(prefs.getBoolean("reward_done_"+k+"_"+t.id,false)&&(t.domain.equals("الإنجليزية والقبول")||t.domain.equals("العمل والدخل")||t.domain.equals("القرآن")||t.domain.equals("المعرفة والقراءة")))sum+=Math.max(0,t.end-t.start);c.add(Calendar.DAY_OF_MONTH,1);}return sum;}
    private int totalPoints(){int n=0;for(String d:domainColors.keySet())n+=domainPoints(d);return n;}private int domainPoints(String d){return prefs.getInt("reward_domain_"+d,0);}private int countDoneIds(String contains){int n=0;for(Map.Entry<String,?>e:prefs.getAll().entrySet())if(e.getKey().startsWith("reward_done_")&&e.getKey().contains(contains)&&Boolean.TRUE.equals(e.getValue()))n++;return n;}private int strongThisWeek(){Calendar c=saturdayStart(Calendar.getInstance()),now=Calendar.getInstance();int n=0;while(!c.after(now)){if(dayRate(c)>=80)n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int streak(){Calendar c=Calendar.getInstance();if(dayRate(c)<80)c.add(Calendar.DAY_OF_MONTH,-1);int n=0;for(int i=0;i<365;i++){if(dayRate(c)>=80){n++;c.add(Calendar.DAY_OF_MONTH,-1);}else break;}return n;}

    private int credits(){return prefs.getInt("reward_credits",0);}private void syncCredits(){Calendar now=Calendar.getInstance();String dk=dateKey(now);SharedPreferences.Editor e=prefs.edit();int add=0;if(dayRate(now)>=80&&!prefs.getBoolean("credit80_"+dk,false)){add+=6;e.putBoolean("credit80_"+dk,true);}if(dayRate(now)>=100&&!prefs.getBoolean("credit100_"+dk,false)){add+=4;e.putBoolean("credit100_"+dk,true);}String wk=now.get(Calendar.YEAR)+"_"+now.get(Calendar.WEEK_OF_YEAR);if(strongThisWeek()>=5&&!prefs.getBoolean("credit_week_"+wk,false)){add+=20;e.putBoolean("credit_week_"+wk,true);}add+=awardOnce(e,"ach_quran20",countDoneIds("quran")>=20,20);add+=awardOnce(e,"ach_english15",countDoneIds("english")>=15,20);add+=awardOnce(e,"ach_work10",countDoneIds("_work")>=10,20);add+=awardOnce(e,"ach_workout8",countDoneIds("workout")>=8,25);add+=awardOnce(e,"ach_leap30",countDoneIds("leap")>=30,25);add+=awardOnce(e,"ach_streak7",streak()>=7,30);if(add>0)e.putInt("reward_credits",credits()+add);e.apply();}
    private int awardOnce(SharedPreferences.Editor e,String key,boolean condition,int amount){if(condition&&!prefs.getBoolean(key,false)){e.putBoolean(key,true);return amount;}return 0;}

    private int levelFor(int p){if(p>=8000)return 6;if(p>=5000)return 5;if(p>=3000)return 4;if(p>=1500)return 3;if(p>=600)return 2;return 1;}private int levelBase(int l){switch(l){case 2:return 600;case 3:return 1500;case 4:return 3000;case 5:return 5000;case 6:return 8000;default:return 0;}}private int levelNext(int l){switch(l){case 1:return 600;case 2:return 1500;case 3:return 3000;case 4:return 5000;case 5:return 8000;default:return 8000;}}private String levelName(int l){switch(l){case 2:return"منطلق";case 3:return"ثابت";case 4:return"متقدم";case 5:return"متمكن";case 6:return"راسخ";default:return"البداية";}}
    private int badgeTier(int p){if(p>=1200)return 4;if(p>=700)return 3;if(p>=350)return 2;if(p>=120)return 1;return 0;}private int badgeNext(int t){switch(t){case 0:return 120;case 1:return 350;case 2:return 700;case 3:return 1200;default:return 1200;}}private String badgeName(int t){switch(t){case 1:return"برونزي";case 2:return"فضي";case 3:return"ذهبي";case 4:return"متمكن";default:return"لم يُفتح";}}

    private boolean matches(Task t){if("الكل".equals(filter))return true;if("قرآن".equals(filter))return"القرآن".equals(t.domain);if("إنجليزية".equals(filter))return"الإنجليزية والقبول".equals(t.domain);if("عمل".equals(filter))return"العمل والدخل".equals(t.domain);if("صحة".equals(filter))return"الصحة".equals(t.domain);if("قراءة".equals(filter))return"المعرفة والقراءة".equals(t.domain);if("أسرة".equals(filter))return"الأسرة".equals(t.domain);return true;}
    private String topBlocker(){try{JSONArray a=new JSONArray(prefs.getString("task_state_events","[]"));LinkedHashMap<String,Integer>m=new LinkedHashMap<>();Calendar lim=Calendar.getInstance();lim.add(Calendar.DAY_OF_MONTH,-30);String lk=dateKey(lim);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null||"تم".equals(o.optString("status"))||o.optString("date").compareTo(lk)<0)continue;String x=o.optString("reason");if(x.isEmpty()||"—".equals(x))continue;m.put(x,m.containsKey(x)?m.get(x)+1:1);}String top="لا توجد بيانات كافية بعد";int max=0;for(String x:m.keySet())if(m.get(x)>max){max=m.get(x);top=x;}return top;}catch(Exception e){return"لا توجد بيانات كافية بعد";}}
    private String blockerAdvice(){String x=topBlocker();if(x.contains("فكرة"))return"احفظ الفكرة في «لاحقًا» ثم عد فورًا.";if(x.contains("يوتيوب")||x.contains("تصفح"))return"افتح الهاتف بهدف واحد وحدد مؤقتًا.";if(x.contains("نوم")||x.contains("تعب"))return"أصلح النوم قبل زيادة الضغط.";if(x.contains("وقت"))return"استخدم نسخة ١٠ دقائق من المهمة.";return"سجّل التأجيل والتعثر ليظهر نمطك الحقيقي.";}
    private String homeMessage(){int p=dayRate(Calendar.getInstance());return p>=100?"اكتمل هدف اليوم. حافظ على النوم والهدوء.":p>=80?"أنت داخل يوم قوي. أكمل بهدوء.":p>=40?"تقدمت جيدًا؛ نفذ المهمة التالية فقط.":"ابدأ بأول مهمة واضحة أمامك.";}

    private String shortDomain(String d){if("الإنجليزية والقبول".equals(d))return"الإنجليزية";if("العمل والدخل".equals(d))return"العمل";if("المعرفة والقراءة".equals(d))return"المعرفة";if("الدين والمسجد".equals(d))return"المسجد";return d;}private String domainShort(String d){if("القرآن".equals(d))return"ق";if("الإنجليزية والقبول".equals(d))return"E";if("العمل والدخل".equals(d))return"ع";if("الصحة".equals(d))return"ص";if("المعرفة والقراءة".equals(d))return"م";if("التواصل".equals(d))return"ت";if("الأسرة".equals(d))return"أ";if("الدين والمسجد".equals(d))return"د";return"ن";}private int color(String d){Integer c=domainColors.get(d);return c==null?GREEN:c;}

    private int pct(int a,int b){if(b<=0)return 0;return Math.max(0,Math.min(100,Math.round(a*100f/b)));}private String formatMinutes(int m){if(m<60)return ar(m)+" د";int h=m/60,mm=m%60;return mm==0?ar(h)+" س":ar(h)+"س "+ar(mm)+"د";}
    private Calendar saturdayStart(Calendar now){Calendar c=(Calendar)now.clone();while(c.get(Calendar.DAY_OF_WEEK)!=Calendar.SATURDAY)c.add(Calendar.DAY_OF_MONTH,-1);return c;}private String dateKey(Calendar c){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(c.getTime());}
    private String format12(int mins){int h=(mins/60)%24,m=mins%60;String ap=h<12?"ص":"م";int hh=h%12;if(hh==0)hh=12;return ar(hh)+":"+(m<10?"٠":"")+ar(m)+" "+ap;}
    private String ar(int n){return String.valueOf(n).replace('0','٠').replace('1','١').replace('2','٢').replace('3','٣').replace('4','٤').replace('5','٥').replace('6','٦').replace('7','٧').replace('8','٨').replace('9','٩');}
    private int soft(int c){return Color.rgb((Color.red(c)+255*6)/7,(Color.green(c)+255*6)/7,(Color.blue(c)+255*6)/7);}

    private ScrollView scroll(){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.setBackgroundColor(BG);s.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return s;}private LinearLayout root(ScrollView s){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(22),dp(18),dp(22),dp(24));r.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);s.addView(r,new ScrollView.LayoutParams(-1,-2));return r;}
