    static class RingView extends View {int value,color;boolean big;Paint p=new Paint(1);public RingView(Activity c,int v,int color,boolean big){super(c);value=v;this.color=color;this.big=big;}protected void onDraw(Canvas c){super.onDraw(c);float s=Math.min(getWidth(),getHeight()),pad=s*.16f;RectF r=new RectF(pad,pad,s-pad,s-pad);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(big?s*.075f:s*.085f);p.setStrokeCap(Paint.Cap.ROUND);p.setColor(Color.rgb(232,235,241));c.drawArc(r,-90,360,false,p);p.setColor(color);c.drawArc(r,-90,360*value/100f,false,p);p.setStyle(Paint.Style.FILL);p.setColor(TEXT);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(s*(big?.22f:.19f));c.drawText(toAr(value)+"٪",s/2,s/2-p.ascent()/3,p);}static String toAr(int n){return String.valueOf(n).replace('0','٠').replace('1','١').replace('2','٢').replace('3','٣').replace('4','٤').replace('5','٥').replace('6','٦').replace('7','٧').replace('8','٨').replace('9','٩');}}
